<?php

namespace RayanLevert\Model\Tests\Model;

use DateTimeImmutable;
use PDO;
use PHPUnit\Framework\Attributes\Test;
use RayanLevert\Model\State;
use RayanLevert\Model\Tests\Fixtures\User;

/**
 * This class is used to test with a **real** database all the queries generated by the Model class
 *
 * Assuring the database *model* is created and table *user* as well
 *
 * - id INT AUTO_INCREMENT PRIMARY KEY
 * - first_name VARCHAR(45) NOT NULL
 * - last_name VARCHAR(45) NOT NULL
 * - created_at DATETIME NOT NULL
 * - age INT NOT NULL
 * - height FLOAT NOT NULL
 */
abstract class TestCase extends \RayanLevert\Model\Tests\TransactionTestCase
{
    #[Test]
    public function createSaveAndDeleteSuccessfully(): void
    {
        $model = new User();

        $model->firstName = 'John';
        $model->lastName  = 'Doe';
        $model->createdAt = new DateTimeImmutable('2026-01-01 12:00:00');
        $model->age       = 20;
        $model->height    = 1.80;

        $this->assertSame(State::TRANSIANT, $model->state);

        // No exception thrown
        $model->create();
        $id = $model->id;

        $this->assertSame(State::PERSISTENT, $model->state);

        // The AutoIncrement column is assigned to the model
        $this->assertNotNull($model->id);
        $this->assertNotSame(0, $model->id);

        $escape = $this->getQueries()->escapeCharacter;

        // Select afterwards
        $oStatement = $this->dataObject->pdo->prepare("SELECT * FROM {$escape}user{$escape}");

        $this->assertTrue($oStatement->execute());
        $this->assertSame(
            [
                'id'         => $id,
                'first_name' => 'John',
                'last_name'  => 'Doe',
                'created_at' => '2026-01-01 12:00:00',
                'age'        => 20,
                'height'     => 1.80
            ],
            $oStatement->fetch(PDO::FETCH_ASSOC)
        );

        // From the find method as well
        $this->assertNotNull($oModel = $model->findFirstByPrimaryKey($id));
        $this->assertSame('John', $oModel->firstName);
        $this->assertSame('Doe', $oModel->lastName);
        $this->assertSame($id, $oModel->id);
        $this->assertSame(20, $oModel->age);
        $this->assertSame(1.80, $oModel->height);

        $model->firstName = 'Jane';
        $model->lastName  = 'Smith';
        $model->age       = 21;
        $model->height    = 1.81;

        // No exception thrown
        $model->save();

        $this->assertSame(State::PERSISTENT, $model->state);

        // The AutoIncrement column is not changed
        $this->assertSame($id, $model->id);

        // Select afterwards
        $oStatement = $this->dataObject->pdo->prepare("SELECT * FROM {$escape}user{$escape}");

        $this->assertTrue($oStatement->execute());
        $this->assertSame(
            [
                'id'         => $model->id,
                'first_name' => 'Jane',
                'last_name'  => 'Smith',
                'created_at' => '2026-01-01 12:00:00',
                'age'        => 21,
                'height'     => 1.81
            ], $oStatement->fetch(PDO::FETCH_ASSOC)
        );

        $model->delete();

        // Select afterwards
        $oStatement = $this->dataObject->pdo->prepare("SELECT * FROM {$escape}user{$escape}");

        $this->assertTrue($oStatement->execute());
        $this->assertEmpty($oStatement->fetch(PDO::FETCH_ASSOC));

        $this->assertSame(State::DETACHED, $model->state);
    }

    #[Test]
    public function findFirstByPrimary(): void
    {
        $model = new User();
        $model->firstName = 'John';
        $model->lastName  = 'Doe';
        $model->createdAt = new DateTimeImmutable('2026-01-01 12:00:00');
        $model->age       = 20;
        $model->height    = 1.80;

        $model->create();

        $this->assertNotNull($oModel = $model->findFirstByPrimaryKey($model->id));
        $this->assertSame('John', $oModel->firstName);
        $this->assertSame('Doe', $oModel->lastName);
        $this->assertSame($model->id, $oModel->id);
        $this->assertSame('2026-01-01 12:00:00', $oModel->createdAt->format('Y-m-d H:i:s'));
        $this->assertSame(20, $oModel->age);
        $this->assertSame(1.80, $oModel->height);

        $this->assertNull($model->findFirstByPrimaryKey($model->id + 1));
    }

    #[Test]
    public function findFirstByColumns(): void
    {
        $model = new User();
        $model->firstName = 'John';
        $model->lastName  = 'Doe';
        $model->createdAt = new DateTimeImmutable('2026-01-01 12:00:00');
        $model->age       = 20;
        $model->height    = 1.80;

        $model->create();

        $this->assertNotNull($oModel = $model->findFirstByColumns(['firstName' => 'John']));
        $this->assertSame('John', $oModel->firstName);
        $this->assertSame('Doe', $oModel->lastName);
        $this->assertSame($model->id, $oModel->id);
        $this->assertSame('2026-01-01 12:00:00', $oModel->createdAt->format('Y-m-d H:i:s'));
        $this->assertSame(20, $oModel->age);
        $this->assertSame(1.80, $oModel->height);

        $this->assertNotNull($oModel = $model->findFirstByColumns(['lastName' => 'Doe']));
        $this->assertSame('Doe', $oModel->lastName);
        $this->assertSame('John', $oModel->firstName);
        $this->assertSame($model->id, $oModel->id);
        $this->assertSame('2026-01-01 12:00:00', $oModel->createdAt->format('Y-m-d H:i:s'));
        $this->assertSame(20, $oModel->age);
        $this->assertSame(1.80, $oModel->height);

        $this->assertNotNull($oModel = $model->findFirstByColumns(['firstName' => 'John', 'lastName' => 'Doe']));
        $this->assertSame('John', $oModel->firstName);
        $this->assertSame('Doe', $oModel->lastName);
        $this->assertSame($model->id, $oModel->id);
        $this->assertSame('2026-01-01 12:00:00', $oModel->createdAt->format('Y-m-d H:i:s'));
        $this->assertSame(20, $oModel->age);
        $this->assertSame(1.80, $oModel->height);

        $this->assertNotNull($oModel = $model->findFirstByColumns(['id' => $model->id]));
        $this->assertSame($model->id, $oModel->id);
        $this->assertSame('John', $oModel->firstName);
        $this->assertSame('Doe', $oModel->lastName);
        $this->assertSame('2026-01-01 12:00:00', $oModel->createdAt->format('Y-m-d H:i:s'));
        $this->assertSame(20, $oModel->age);
        $this->assertSame(1.80, $oModel->height);

        $this->assertNull($model->findFirstByColumns(['firstName' => 'Jane']));
    }

    #[Test]
    public function findAllByColumns(): void
    {
        $model = new User();
        $model->firstName = 'John';
        $model->lastName  = 'Doe';
        $model->createdAt = new DateTimeImmutable('2026-01-01 12:00:00');
        $model->age       = 20;
        $model->height    = 1.80;

        $model->create();

        $aModels = iterator_to_array($model->findAllByColumns(['firstName' => 'John']));

        $this->assertCount(1, $aModels);
        $this->assertSame('John', $aModels[0]->firstName);
        $this->assertSame('Doe', $aModels[0]->lastName);
        $this->assertSame($model->id, $aModels[0]->id);
        $this->assertSame('2026-01-01 12:00:00', $aModels[0]->createdAt->format('Y-m-d H:i:s'));
        $this->assertSame(20, $aModels[0]->age);
        $this->assertSame(1.80, $aModels[0]->height);

        $aModels = iterator_to_array($model->findAllByColumns(['lastName' => 'Doe']));

        $this->assertCount(1, $aModels);
        $this->assertSame('Doe', $aModels[0]->lastName);
        $this->assertSame('John', $aModels[0]->firstName);
        $this->assertSame($model->id, $aModels[0]->id);
        $this->assertSame('2026-01-01 12:00:00', $aModels[0]->createdAt->format('Y-m-d H:i:s'));
        $this->assertSame(20, $aModels[0]->age);
        $this->assertSame(1.80, $aModels[0]->height);

        $aModels = iterator_to_array($model->findAllByColumns(['firstName' => 'John', 'lastName' => 'Doe']));

        $this->assertCount(1, $aModels);
        $this->assertSame('John', $aModels[0]->firstName);
        $this->assertSame('Doe', $aModels[0]->lastName);
        $this->assertSame($model->id, $aModels[0]->id);
        $this->assertSame('2026-01-01 12:00:00', $aModels[0]->createdAt->format('Y-m-d H:i:s'));
        $this->assertSame(20, $aModels[0]->age);
        $this->assertSame(1.80, $aModels[0]->height);

        $aModels = iterator_to_array($model->findAllByColumns(['id' => $model->id]));

        $this->assertCount(1, $aModels);
        $this->assertSame($model->id, $aModels[0]->id);
        $this->assertSame('John', $aModels[0]->firstName);
        $this->assertSame('Doe', $aModels[0]->lastName);
        $this->assertSame('2026-01-01 12:00:00', $aModels[0]->createdAt->format('Y-m-d H:i:s'));
        $this->assertSame(20, $aModels[0]->age);
        $this->assertSame(1.80, $aModels[0]->height);

        $this->assertEmpty(iterator_to_array($model->findAllByColumns(['firstName' => 'Jane'])));
    }
}
